void kernel_doitgen(int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

#pragma scop
  DATA_TYPE sum_priv[NP];
#pragma omp parallel for private(q, p, s, sum_priv) collapse(2) schedule(static)
  for (r = 0; r < _PB_NR; r++)
    for (q = 0; q < _PB_NQ; q++)  {
      for (p = 0; p < _PB_NP; p++)  {
	sum_priv[p] = SCALAR_VAL(0.0);
	for (s = 0; s < _PB_NP; s++)
	  sum_priv[p] += A[r][q][s] * C4[s][p];
      }
      for (p = 0; p < _PB_NP; p++)
	A[r][q][p] = sum_priv[p];
    }
#pragma endscop

}
